insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (6,'九六四二、一一〇二零',array['投資型人壽死亡給付÷保單帳戶價值 最低比率（現行七段制）','16-30歲 190%｜31-40歲 160%｜41-50歲 140%｜51-60歲 120%','61-70歲 110%｜71-90歲 102%｜91歲以上 100%','記法：1後面接 9、6、4、2、1，最後 02、00','⚠ 舊講義的 130%／115%／101% 三段制已過時，不要再背']::text[],'ai_generated',false,'{847,880}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (6,'全委無「衍對避結」；非全委無「股期台」',array['全委（保險人代操）不能連結：衍生性商品、對沖基金、避險基金、結構型商品','非全委（要保人自選）不能連結：股票、期貨、台灣存託憑證','反過來：股票、台灣存託憑證只有全委才有']::text[],'original',false,'{62,63,64,81}');
