insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (6,'不賣不換不移；不擔不借不違法',array['第8條 專設帳簿 vs 一般帳簿：不得互相出售、交換、移轉（例外要用銀行存款或現金）','第5條 運用專設帳簿：不得提供擔保、不得借予他人、不得從事法令禁止投資']::text[],'original',false,'{6,23,24,91}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (5,'銀杏濃魚油',array['申報辦法所稱銀行業：銀（銀行）、杏（信用合作社）、濃（農會信用部）、魚（漁會信用部）、油（郵政）','法條另含全國農業金庫；題目沒列時照題目全選']::text[],'original',false,'{13}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (5,'公五千、個五百、非居十萬',array['逕行辦理：公司/行號 每年 5,000 萬美元以內；團體/個人 每年 500 萬美元以內；非居住民 每筆 10 萬美元以內','經銀行業確認文件：公司/行號 每筆 100 萬美元以上；團體/個人 每筆 50 萬美元以上','經央行核准：超過上述年度額度、非居住民每筆超過 10 萬美元','⚠ 舊講義「年滿20歲／未滿20歲」：法規已改為 18 歲（112.1.1 生效），題庫選項仍寫二十歲時照題作答']::text[],'original',false,'{82,848,849,881,914,944,945}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (5,'自家五千萬、信託不佔額、央行專案',array['壽險業匯出國外投資資金三管道：','1. 用壽險業者自己每年 5 千萬美元累積結匯額度','2. 經金融機構特定金錢信託投資國外（不佔用任何人額度）','3. 向「中央銀行」專案申請核准（不是金管會）','不能用要保人的結匯額度']::text[],'original',false,'{850,915,946,983,986}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (5,'誰付錢誰結匯、誰領錢誰結匯',array['外幣保單繳保費要換外幣→要保人逕向銀行業結匯','領保險金要換回新臺幣→受益人逕向銀行業結匯','例外：外幣投資型年金轉即期年金約定新臺幣給付→由保險業結匯']::text[],'ai_generated',false,'{50,79,58,104}');
