insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (3,'死營利、危附利、宣危附利',array['外幣非投資型人壽：預定死亡率、預定營業費用率、預定利率','傳統型年金：預定危險發生率、預定附加費用率、預定利率','利率變動型年金：再加「宣告利率」']::text[],'original',false,'{898,931,958,959}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (3,'人健年；美歐澳人',array['外幣非投資型險種：人壽、健康、年金（須經中央銀行許可），沒有傷害險','已開放幣別：美元、歐元、澳幣、人民幣（人民幣繳費年期至少 4 年）']::text[],'original',false,'{885,917,930,868}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (3,'半年自查、年稽核、年一時',array['業務單位專案自行查核：每半年（舊講義寫每季，以題庫為準）','內部稽核專案查核：每年（項目：招攬核保理賠精算保全法務投資，沒有開發）','業務員在職訓練：每年至少 1 小時「匯率風險及外匯相關法規」','向要保人揭露解約金等折合新臺幣：每年至少 1 次（不是每半年）']::text[],'original',false,'{115,116,118,77,78,51}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (2,'許可找央行、核准找金管',array['外匯業務（含再保險、外幣保單、外投年轉臺）→中央銀行「許可」','保險商品（第一張外幣非投資型等）→主管機關（金管會）「核准」']::text[],'original',false,'{917,909,984,910,123}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (2,'外投年轉臺',array['外幣「投資型」年金，累積期滿轉一般帳簿即期年金→可約定新臺幣給付','這種情形的結匯由「保險業」辦理','非投資型年金不適用']::text[],'original',false,'{37,104,877}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (2,'退回書件、駁回資格、半年不開就撤',array['退回（第7條）：書件不完備、應記載事項不充分','駁回（第8條）：資格不符第5條、最近1年違反外匯規定情節重大','廢止撤銷（第9條）：許可函後 6 個月內未開辦（可延 3 個月一次）、停業解散破產等']::text[],'original',false,'{2,55,36,56,19}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (4,'政國軍罰歸金管；調指調審歸央行',array['行政主管機關（金管會）：政府及公營事業外幣債權債務、國庫對外債務、軍政機關進口外匯、罰鍰、攜帶外幣限額','業務機關（央行）：外匯調度、指定銀行並督導、調節供需、審核匯出入款','停止第7、13、17條→行政院（恢復要送立法院追認）；學校捐贈免結匯→財政部']::text[],'original',false,'{10,27,43,96,68,12,98,29,11}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (7,'十、廿五、三十、卅五、超卅五、超四十',array['10%：交易處理程序＋風控措施，經董事會通過','25%：最近1年內控無重大缺失＋簽證精算或外部機構評估＋投資手冊','30%：最近1年無重大裁罰及處分','35%：風險值每週控管、攤銷後成本每半年報董事會、最近2年無罰鍰、風控長','超過35%：35%核准已逾1年＋董事會每年訂限額＋RBC 法定1.25倍(250%)或 AA-','超過40%：RBC 最近1年及3年平均都達1.25倍或 AA+＋內部風險模型']::text[],'original',false,'{893,925,991,860,963,976}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (7,'二年二億、五年五億、合計二趴',array['對沖基金經理公司：管理歷史滿 2 年、資產 2 億美元','私募基金管理機構：滿 5 年、5 億美元','對沖＋私募（加計私募公司債）總額≤可運用資金 2%；其他基金每一≤資金5%＆已發行10%']::text[],'original',false,'{855,889,920,888,950}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (7,'五金；A負二十一',array['國際性組織債券：A-、每一組織≤資金 5%（五金）','資產證券化：A-、總額≤國外投資額度 20%、每一≤資金 1%']::text[],'original',false,'{856,890,989,921,951}');
insert into mnemonic_cards(chapter_id,phrase,meaning,source,approved,related_question_ids) values (7,'不動產：並生效益、一資十權、六月匯回',array['投資時已合法利用「並」產生利用效益','總額≤資金 1% 及業主權益 10%','特定目的事業收入→簽證後 6 個月內匯回母公司；年度終了 3 個月內報備查','每一標的事前逐筆向主管機關申請核准；信託受託機構 BBB+']::text[],'original',false,'{922,952,954,858,924,995,1026}');
update questions set plain_explanation='保險人運用專設帳簿的資產去投資、交易，每一筆都要留下書面紀錄，而且「按月」提出檢討報告、依法建檔保存。專設帳簿是保戶的錢，所以檢討頻率訂得比較密，按季、每半年、按週都不對，答案是4。', plain_explanation_reviewed=false where id=122 and (plain_explanation is null or plain_explanation='');
update questions set plain_explanation='新臺幣投資型保險用要保人的保費去買國外有價證券時，是壽險業者「代」要保人結匯，所以銀行要看三樣東西：壽險業者填的結匯申報書、要保人委託壽險業者辦理結匯的授權書、保戶清冊（含姓名、身分證號、出生日期、結匯金額）。申報書是業者填的，不是要保人自己填，所以D不選，答案是ABC。', plain_explanation_reviewed=false where id=1021 and (plain_explanation is null or plain_explanation='');
update questions set plain_explanation='人民幣保單開放時，主管機關另外對人民幣商品設有銷售限額，額度由主管機關規定、可能隨政策調整，所以題目不會考固定的20%或10%，也不是沒有限額。答案是「應依主管機關規定之銷售限額辦理」，選4。', plain_explanation_reviewed=false where id=1007 and (plain_explanation is null or plain_explanation='');
